<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/services_v1380.php';sk1380_require_login('/my-services.php');$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$act=(string)($_POST['action']??'');if($act==='accept_quote'){$qid=(int)$_POST['quote_id'];$q=sk1380_db()->prepare('SELECT q.*,r.customer_user_id,r.title,r.address_text,r.area,r.status request_status FROM service_quotes_v1380 q JOIN service_requests_v1380 r ON r.id=q.request_id WHERE q.tenant_id=? AND q.id=? AND r.customer_user_id=? AND q.status="submitted" LIMIT 1');$q->execute([sk1380_tid(),$qid,sk1380_uid()]);$x=$q->fetch(PDO::FETCH_ASSOC);if(!$x)throw new RuntimeException('Quote is no longer available.');$pdo=sk1380_db();$pdo->beginTransaction();$code='SV-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8));$pdo->prepare('INSERT INTO service_orders_v1380(tenant_id,customer_user_id,provider_id,request_id,quote_id,order_code,service_title,address_text,area,subtotal,visit_fee,total_amount,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,"booked",NOW(),NOW())')->execute([sk1380_tid(),sk1380_uid(),$x['provider_id'],$x['request_id'],$qid,$code,$x['title'],$x['address_text'],$x['area'],$x['amount'],$x['visit_fee'],(float)$x['amount']+(float)$x['visit_fee']]);$oid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE service_quotes_v1380 SET status=IF(id=?,"accepted","declined"),updated_at=NOW() WHERE tenant_id=? AND request_id=?')->execute([$qid,sk1380_tid(),$x['request_id']]);$pdo->prepare('UPDATE service_requests_v1380 SET status="booked",selected_quote_id=?,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$qid,sk1380_tid(),$x['request_id']]);$pdo->commit();sk1380_log_order($oid,'booked','Customer accepted provider quote.');$msg='Quote accepted. Booking created: '.$code;}elseif($act==='cancel_request'){$rid=(int)$_POST['request_id'];sk1380_db()->prepare('UPDATE service_requests_v1380 SET status="cancelled",updated_at=NOW() WHERE tenant_id=? AND id=? AND customer_user_id=? AND status IN("open","quoted")')->execute([sk1380_tid(),$rid,sk1380_uid()]);$msg='Request cancelled.';}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}$q=sk1380_db()->prepare('SELECT r.*,c.name category_name,(SELECT COUNT(*) FROM service_quotes_v1380 sq WHERE sq.tenant_id=r.tenant_id AND sq.request_id=r.id AND sq.status="submitted") live_quotes FROM service_requests_v1380 r JOIN service_categories_v1380 c ON c.id=r.category_id WHERE r.tenant_id=? AND r.customer_user_id=? ORDER BY r.id DESC LIMIT 60');$q->execute([sk1380_tid(),sk1380_uid()]);$reqs=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$o=sk1380_db()->prepare('SELECT o.*,p.business_name,p.display_name FROM service_orders_v1380 o JOIN service_provider_profiles_v1380 p ON p.id=o.provider_id WHERE o.tenant_id=? AND o.customer_user_id=? ORDER BY o.id DESC LIMIT 60');$o->execute([sk1380_tid(),sk1380_uid()]);$orders=$o->fetchAll(PDO::FETCH_ASSOC)?:[];sk1380_shell('My Service Bookings','customer-dash');?><section class="dash-hero"><div><span class="eyebrow">CUSTOMER DASHBOARD</span><h1>My Service Requests & Bookings</h1></div><a class="btn" href="/request-service.php">+ New Request</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="dash-columns"><section><h2>Requests</h2><?php foreach($reqs as $r):?><article class="request-card"><div><span><?=sk1380_h($r['category_name'])?></span><h3><?=sk1380_h($r['title'])?></h3><p><?=sk1380_h($r['area'])?> · <?=sk1380_h($r['urgency'])?> · <?=sk1380_h($r['status'])?></p></div><b><?=$r['live_quotes']?> quotes</b><?php if($r['live_quotes']):$z=sk1380_db()->prepare('SELECT q.*,p.business_name,p.display_name,p.rating_avg FROM service_quotes_v1380 q JOIN service_provider_profiles_v1380 p ON p.id=q.provider_id WHERE q.tenant_id=? AND q.request_id=? AND q.status="submitted" ORDER BY q.amount ASC');$z->execute([sk1380_tid(),$r['id']]);foreach($z->fetchAll(PDO::FETCH_ASSOC)?:[] as $x):?><div class="quote"><div><b><?=sk1380_h($x['business_name']?:$x['display_name'])?></b><small><?=number_format((float)$x['rating_avg'],1)?> ★ · <?=sk1380_h($x['message'])?></small></div><strong>PKR <?=number_format((float)$x['amount']+(float)$x['visit_fee'],0)?></strong><form method="post"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="accept_quote"><input type="hidden" name="quote_id" value="<?=$x['id']?>"><button>Accept & Book</button></form></div><?php endforeach;endif;?><?php if(in_array($r['status'],['open','quoted'],true)):?><form method="post" class="inline"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="cancel_request"><input type="hidden" name="request_id" value="<?=$r['id']?>"><button class="linkbtn">Cancel request</button></form><?php endif;?></article><?php endforeach;?></section><section><h2>Bookings</h2><?php foreach($orders as $x):?><a class="order-card" href="/service-order.php?id=<?=$x['id']?>"><span><?=sk1380_h($x['order_code'])?></span><h3><?=sk1380_h($x['service_title'])?></h3><p><?=sk1380_h($x['business_name']?:$x['display_name'])?></p><b><?=sk1380_h(strtoupper($x['status']))?></b><strong>PKR <?=number_format((float)$x['total_amount'],0)?></strong></a><?php endforeach;?></section></div><?php sk1380_end();